const agencySetupFacts = `-- name: AgencySetupFacts :one
SELECT
  (SELECT count(*) FROM providers p WHERE p.workspace_id = $1 AND p.disconnected_at IS NULL)::bigint AS providers,
  (SELECT count(*) FROM sending_domains d WHERE d.workspace_id = $1 AND d.status = 'verified')::bigint AS verified_domains,
  (SELECT coalesce(min(d.domain), '') FROM sending_domains d WHERE d.workspace_id = $1)::text AS first_domain,
  (SELECT count(*) FROM workspace_members m JOIN roles r ON r.id = m.role_id
     WHERE m.workspace_id = $1 AND m.status = 'active' AND r.key IN ('client_approver', 'client_viewer'))::bigint AS client_members,
  (SELECT count(*) FROM invitations i JOIN roles r ON r.id = i.role_id
     WHERE i.workspace_id = $1 AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
       AND r.key IN ('client_approver', 'client_viewer'))::bigint AS client_invites
`

